#!/usr/bin/env bash
# AKFC — Laboratoire de rendu : TOUS les types de blocs, par leurs vraies vues.
#  - nouveau RealBlocksPreview : rend chaque type via le registre des blocs (les vues du site),
#    sur des données d'exemple et des médias factices (SVG, audio silencieux) :
#      texte · média-texte (image, logo du site, avatar — alternés comme sur une page) ·
#      texte enrobant (gauche, droite) · galerie (grille, carrousel, mosaïque) · audio · documents
#  - remplace les imitations (collections, enrobage, pleine largeur) ; les ancres des réglages
#    (lab-blocs, lab-collections, lab-float, lab-pleine-largeur) pointent sur les vrais rendus.
#  - garde-fou : un nouveau type de bloc sans exemple dans le laboratoire = erreur de compilation.
#  Preuve avant commit : pnpm check (sinon TOUT est restauré).
# Usage : bash apply-design-lab-all-blocks.sh   (AKFC_APPLY_ONLY=1 : applique sans vérifier ni committer)
set -euo pipefail
[ -f "package.json" ] || { echo "ERREUR: racine du repo." >&2; exit 1; }
N="apps/web/src/features/design-lab/RealBlocksPreview.tsx"; L="apps/web/src/features/design-lab/BlockStyleLab.tsx"
[ -f "$N" ] && { echo "— déjà appliqué"; exit 0; }
[ -f "$L" ] || { echo "ERREUR: $L introuvable." >&2; exit 1; }
BK=/tmp/akfc_lab_backup; rm -rf "$BK"; mkdir -p "$BK"; cp "$L" "$BK/lab"
restore(){ cp "$BK/lab" "$L"; rm -f "$N"; echo "↩ fichiers restaurés à l'identique (aucun commit)."; }
W=/tmp/akfc_lab; rm -rf "$W"; mkdir -p "$W"
echo '' | base64 -d > "$W/edit.py"

echo "== application =="
echo '' | base64 -d > "$N" && echo "  ok  $N"
python3 "$W/edit.py" . || { restore; exit 1; }
if [ "${AKFC_APPLY_ONLY:-0}" = "1" ]; then echo "APPLY_ONLY"; exit 0; fi

echo "== pnpm check =="
if ! pnpm check > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"; grep -nE "conventions Next|error TS|Error:" /tmp/akfc_tc.log | head -15; restore; exit 1
fi
echo "  ✅ check OK"
git add "$N" "$L"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
feat(design-lab): tous les types de blocs et leurs variantes, rendus par les vraies vues

